document.addEventListener("DOMContentLoaded",function(){const n=document.getElementById("smart-home-form");n&&n.addEventListener("submit",function(n){n.preventDefault();const e=parseFloat(document.getElementById("homeSize").value),t=parseFloat(document.getElementById("monthlyUtility").value),a=parseFloat(document.getElementById("energyRate").value),o=parseFloat(document.getElementById("thermostatCost").value)||0,r=parseFloat(document.getElementById("lightingCost").value)||0,i=parseFloat(document.getElementById("securityCost").value)||0,s=parseFloat(document.getElementById("plugsCost").value)||0,d=parseFloat(document.getElementById("waterCost").value)||0,l=parseFloat(document.getElementById("energySavingsPercent").value)/100,c=parseFloat(document.getElementById("insuranceDiscount").value)/100,g=o+r+i+s+d,m=12*t,u=m*l,v=parseFloat(document.getElementById("annualInsurance").value)*c,p=.15*e,y=.8*g,b=u+v+p,h=g/b,f=10*b,$=f-g+y,S=($-g)/g*100,I=[];if(o>0){const n=.15*m;I.push({name:"Smart Thermostat",cost:o,annualSavings:n,payback:o/n})}if(r>0){const n=.08*m;I.push({name:"Smart Lighting",cost:r,annualSavings:n,payback:r/n})}if(i>0){const n=v+.3*p;I.push({name:"Security System",cost:i,annualSavings:n,payback:i/n})}I.sort((n,e)=>n.payback-e.payback);document.getElementById("smart-home-result").innerHTML=`\n      <h3>🏠 Smart Home Investment Analysis</h3>\n      \n      <div class="insight-cards">\n        <div class="insight-card warning">\n          <h6>💰 Total Investment</h6>\n          <div class="big-number">$${g.toLocaleString()}</div>\n          <p>Upfront device costs<br>\n          Property value: +$${y.toLocaleString()}<br>\n          ${Math.round(10*h)/10} year payback</p>\n        </div>\n        \n        <div class="insight-card success">\n          <h6>💡 Annual Savings</h6>\n          <div class="big-number">$${Math.round(b).toLocaleString()}</div>\n          <p>Energy: $${Math.round(u).toLocaleString()}<br>\n          Insurance: $${Math.round(v).toLocaleString()}<br>\n          Maintenance: $${Math.round(p).toLocaleString()}</p>\n        </div>\n        \n        <div class="insight-card info">\n          <h6>📈 10-Year ROI</h6>\n          <div class="big-number">${Math.round(S)}%</div>\n          <p>Net benefit: $${Math.round($).toLocaleString()}<br>\n          Total savings: $${Math.round(f).toLocaleString()}<br>\n          ${S>100?"Excellent":S>50?"Good":S>0?"Positive":"Poor"} investment</p>\n        </div>\n      </div>\n\n      <div style="margin-top: 2rem; padding: 1.5rem; background: #f8f9fa; border-radius: 12px;">\n        <h4>📊 Device Priority Analysis</h4>\n        \n        ${I.length>0?`\n        <div style="display: grid; gap: 1rem; margin-top: 1rem;">\n          ${I.map((n,e)=>`\n            <div style="display: flex; justify-content: space-between; align-items: center; padding: 1rem; background: white; border-radius: 8px; border-left: 4px solid ${0===e?"#28a745":1===e?"#17a2b8":"#ffc107"};">\n              <div>\n                <strong>${e+1}. ${n.name}</strong><br>\n                <small>Cost: $${n.cost.toLocaleString()} | Annual savings: $${Math.round(n.annualSavings).toLocaleString()}</small>\n              </div>\n              <div style="text-align: right;">\n                <strong>${Math.round(10*n.payback)/10} years</strong><br>\n                <small>Payback period</small>\n              </div>\n            </div>\n          `).join("")}\n        </div>\n        `:"<p>No devices selected for analysis.</p>"}\n        \n        <div style="margin-top: 1.5rem; display: grid; grid-template-columns: 1fr 1fr; gap: 1rem;">\n          <div style="padding: 1rem; background: #e8f5e8; border-radius: 8px;">\n            <strong>💚 Energy Benefits:</strong><br>\n            • ${100*l}% reduction in utility costs<br>\n            • $${Math.round(u/12).toLocaleString()} monthly savings<br>\n            • ${Math.round(u/a).toLocaleString()} kWh saved annually<br>\n            • Reduced carbon footprint\n          </div>\n          \n          <div style="padding: 1rem; background: #e3f2fd; border-radius: 8px;">\n            <strong>🛡️ Additional Benefits:</strong><br>\n            • Enhanced home security & monitoring<br>\n            • Improved comfort & convenience<br>\n            • Remote control & automation<br>\n            • Potential insurance discounts\n          </div>\n        </div>\n        \n        <div style="margin-top: 1rem; padding: 1rem; background: ${h<=3?"#d4edda":h<=7?"#fff3cd":"#f8d7da"}; border-radius: 8px; border-left: 4px solid ${h<=3?"#28a745":h<=7?"#ffc107":"#dc3545"};">\n          <strong>💡 Investment Recommendation:</strong><br>\n          ${h<=3?"🎯 Excellent investment! These devices will pay for themselves quickly and provide long-term value.":h<=7?"✅ Good investment with reasonable payback period. Consider starting with highest-priority devices.":"⚠️ Longer payback period. Focus on devices with best ROI or consider reducing costs."}\n        </div>\n      </div>\n    `})});